26	  if (arg('--dither') !== undefined) vq.set('dither', arg('--dither'));
27	  const view = vq.toString();
28	  const spine = JSON.parse(fs.readFileSync(path.join(ROOT, segDir, 'spine.json'), 'utf8'));
29	  const LIB = 'toolkit/factory/world/', inputs = path.join(ROOT, segDir, 'inputs.json');
30	  const files = [LIB + 'lib3d.js', LIB + 'core.js', LIB + 'page.html', LIB + 'render_shots.js', LIB + 'vendor/package.json', `${segDir}/scene.js`,
31	    `${segDir}/spine.json`, ...(fs.existsSync(inputs) ? JSON.parse(fs.readFileSync(inputs)) : [])];
32	  const codeHash = crypto.createHash('sha256'); for (const f of files) codeHash.update(f + '\0' + fs.readFileSync(path.join(ROOT, f)));
